<?php declare(strict_types=1); final class NotificationController extends Controller { public function index(): void { AuthMiddleware::handle(); $id=(int)Session::get('user_id');$db=Database::connection();$s=$db->prepare('SELECT * FROM notifications WHERE user_id=:id ORDER BY created_at DESC LIMIT 100');$s->execute(['id'=>$id]);$this->view('notifications/index',['title'=>'اعلان‌ها','notifications'=>$s->fetchAll()],Session::get('role')==='employer'?'employer':'dashboard'); } public function read(): void { AuthMiddleware::handle();if(CSRF::verify($_POST['_csrf']??null)){$s=Database::connection()->prepare('UPDATE notifications SET read_at=NOW() WHERE id=:id AND user_id=:uid');$s->execute(['id'=>(int)$_POST['id'],'uid'=>(int)Session::get('user_id')]);}$this->redirect('/notifications'); } public function readAll(): void { AuthMiddleware::handle();if(CSRF::verify($_POST['_csrf']??null))Database::connection()->prepare('UPDATE notifications SET read_at=NOW() WHERE user_id=:uid AND read_at IS NULL')->execute(['uid'=>(int)Session::get('user_id')]);$this->redirect('/notifications'); } }